import { useEffect, useMemo, useRef, useState } from 'react';
import {
  DRILL_SIZE,
  builderJoiner,
  builderSentence,
  builderTiles,
  directionOf,
  drillOrder,
  sameSentence,
  seededRng,
  shuffleTiles,
} from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { ModeScreen, ModeSummary } from '../ModeScreen.js';
import type { ModeProps } from '../ModeRoute.js';
import { drillWords } from '../data.js';
import { missedWords, useModeRun } from '../useModeRun.js';
import styles from '../Modes.module.css';

/** One sentence to rebuild: the word it belongs to, its tiles in order, and the order shown. */
interface Item {
  wordId: string;
  headword: string;
  meaning: string;
  sentence: string;
  tiles: string[];
  shown: number[];
}

/**
 * Sentence builder: one of the learner's own example sentences, cut into
 * tiles and shuffled, to be tapped back into order. A right-to-left
 * language builds right to left; each tile carries its language, so a
 * mixed-script example reads correctly. Backspace takes the last tile back.
 *
 * It counts for the schedule like a cloze (card type builder, source
 * session).
 */
export function Builder({ view, lang, meaningLang }: ModeProps): React.JSX.Element {
  const run = useModeRun('builder');
  const items = useMemo<Item[]>(() => {
    const rng = seededRng(run.seed);
    return drillOrder(drillWords('builder', view.words, lang), view.today, rng)
      .slice(0, DRILL_SIZE)
      .flatMap((word) => {
        const sentence = builderSentence(word, lang);
        if (sentence === undefined) return [];
        const tiles = builderTiles(sentence, lang);
        return [
          {
            wordId: word.id,
            headword: word.headword,
            meaning: word.meaning,
            sentence,
            tiles,
            shown: shuffleTiles(tiles, rng),
          },
        ];
      });
    // A new list per run, not per answer (every answer changes the words' progress).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [run.seed]);
  const [index, setIndex] = useState(0);
  const [placed, setPlaced] = useState<number[]>([]);
  const [outcome, setOutcome] = useState<'correct' | 'wrong' | undefined>(undefined);
  const shownAt = useRef(0);
  const item = items[index];
  const dir = directionOf(lang);
  const joiner = builderJoiner(lang);

  useEffect(() => {
    shownAt.current = Date.now();
  }, [index, run.seed]);

  // Backspace takes the last tile back, while the answer is open.
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      if (event.key !== 'Backspace' || outcome !== undefined) return;
      const target = event.target as HTMLElement | null;
      if (target?.tagName === 'INPUT' || target?.tagName === 'TEXTAREA') return;
      event.preventDefault();
      setPlaced((list) => list.slice(0, -1));
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [outcome]);

  if (item === undefined) {
    return (
      <ModeSummary
        title={t('modes.builder')}
        lang={lang}
        score={t('modes.scoreOf', {
          right: run.answers.filter((a) => a.correct).length,
          total: run.answers.length,
        })}
        missed={missedWords(run.answers)}
        onAgain={() => {
          run.restart();
          setIndex(0);
          setPlaced([]);
          setOutcome(undefined);
        }}
      />
    );
  }

  const complete = placed.length === item.tiles.length;
  const check = (): void => {
    if (!complete || outcome !== undefined) return;
    const correct = sameSentence(
      placed.map((i) => item.tiles[i] ?? ''),
      item.tiles,
    );
    setOutcome(correct ? 'correct' : 'wrong');
    void run.record({
      wordId: item.wordId,
      headword: item.headword,
      correct,
      typed: placed.map((i) => item.tiles[i] ?? '').join(joiner),
      latencyMs: Date.now() - shownAt.current,
    });
  };
  const next = (): void => {
    setPlaced([]);
    setOutcome(undefined);
    setIndex(index + 1);
  };

  return (
    <ModeScreen
      title={t('modes.builder')}
      ask={t('modes.builderAsk')}
      counts
      progress={{ done: index, total: items.length }}
      said={
        outcome === 'correct'
          ? t('modes.builderRight')
          : outcome === 'wrong'
            ? `${t('modes.builderWrong')} ${item.sentence}`
            : ''
      }
      actions={
        outcome === undefined ? (
          <div className={styles.row}>
            <button
              type="button"
              className={styles.secondary}
              disabled={placed.length === 0}
              onClick={() => {
                setPlaced([]);
              }}
            >
              {t('modes.clear')}
            </button>
            <button type="button" className={styles.primary} disabled={!complete} onClick={check}>
              {t('modes.check')}
            </button>
          </div>
        ) : (
          <button type="button" className={styles.primary} onClick={next}>
            {t('modes.next')}
          </button>
        )
      }
    >
      {item.meaning !== '' && (
        <p className={styles.note}>
          <Bilingual lang={lang}>{item.headword}</Bilingual>
          {' — '}
          <Bilingual lang={meaningLang}>{item.meaning}</Bilingual>
        </p>
      )}
      <div
        className={cx(
          styles.answerRow,
          outcome === 'correct' && styles.answerRowRight,
          outcome === 'wrong' && styles.answerRowWrong,
        )}
        dir={dir}
        role="group"
        aria-label={t('modes.builderAnswer')}
      >
        {placed.length === 0 ? (
          <span className={styles.placeholder} dir="ltr">
            {t('modes.builderEmpty')}
          </span>
        ) : (
          placed.map((tileIndex, position) => {
            const tile = item.tiles[tileIndex] ?? '';
            return (
              <button
                key={`${String(tileIndex)}-${String(position)}`}
                type="button"
                className={cx(styles.chipTile, styles.chipPlaced)}
                aria-label={t('modes.builderTakeBack', { word: tile })}
                disabled={outcome !== undefined}
                onClick={() => {
                  setPlaced((list) => list.filter((_, i) => i !== position));
                }}
              >
                <Bilingual lang={lang}>{tile}</Bilingual>
              </button>
            );
          })
        )}
      </div>
      <div className={styles.tray} dir={dir} role="group" aria-label={t('modes.builderTiles')}>
        {item.shown.map((tileIndex) => {
          const tile = item.tiles[tileIndex] ?? '';
          const used = placed.includes(tileIndex);
          return (
            <button
              key={tileIndex}
              type="button"
              className={cx(styles.chipTile, used && styles.chipUsed)}
              disabled={used || outcome !== undefined}
              aria-label={t('modes.builderPlace', { word: tile })}
              onClick={() => {
                setPlaced((list) => (list.includes(tileIndex) ? list : [...list, tileIndex]));
              }}
            >
              <Bilingual lang={lang}>{tile}</Bilingual>
            </button>
          );
        })}
      </div>
      {outcome === 'wrong' && (
        <div className={styles.reveal}>
          <span className={styles.revealLabel}>{t('modes.builderWrong')}</span>
          <Bilingual lang={lang} block className={styles.solution}>
            {item.sentence}
          </Bilingual>
        </div>
      )}
    </ModeScreen>
  );
}
